ALTER TABLE `UserData` ADD `guidanceLevel` enum('FULL','HINTS','OFF') DEFAULT 'FULL' NOT NULL;
ALTER TABLE `UserData` ADD `seenIntros` json DEFAULT ('[]') NOT NULL;
ALTER TABLE `UserData` ADD `playedBefore` boolean DEFAULT false NOT NULL;
ALTER TABLE `UserPet` ADD `isSanctuaryPup` boolean DEFAULT false NOT NULL;

-- The Academy Trials were reordered; move every saved tutorial step from its old index
-- to the same lesson's new index (removed lessons go to the next one that remains).
UPDATE `UserData`
SET `tutorialStep` = CASE `tutorialStep`
    WHEN 0 THEN 0
    WHEN 1 THEN 0
    WHEN 2 THEN 0
    WHEN 3 THEN 0
    WHEN 4 THEN 12
    WHEN 5 THEN 12
    WHEN 6 THEN 12
    WHEN 7 THEN 12
    WHEN 8 THEN 12
    WHEN 9 THEN 7
    WHEN 10 THEN 7
    WHEN 11 THEN 8
    WHEN 12 THEN 9
    WHEN 13 THEN 12
    WHEN 14 THEN 13
    WHEN 15 THEN 15
    WHEN 16 THEN 16
    WHEN 17 THEN 19
    WHEN 18 THEN 20
    WHEN 19 THEN 17
    WHEN 20 THEN 17
    WHEN 21 THEN 17
    WHEN 22 THEN 17
    WHEN 23 THEN 17
    WHEN 24 THEN 18
    WHEN 25 THEN 24
    WHEN 26 THEN 25
    WHEN 27 THEN 26
    WHEN 28 THEN 27
    WHEN 29 THEN 28
    WHEN 30 THEN 30
    WHEN 31 THEN 30
    WHEN 32 THEN 31
    WHEN 33 THEN 32
    WHEN 34 THEN 33
    WHEN 35 THEN 34
    WHEN 36 THEN 35
    WHEN 37 THEN 36
    WHEN 38 THEN 36
    WHEN 39 THEN 37
    WHEN 40 THEN 37
    WHEN 41 THEN 38
    WHEN 42 THEN 41
    WHEN 43 THEN 42
    WHEN 44 THEN 43
    WHEN 45 THEN 44
    WHEN 46 THEN 45
    WHEN 47 THEN 46
    WHEN 48 THEN 49
    ELSE `tutorialStep`
  END
WHERE `tutorialStep` <= 48;

-- The arena trial moved behind the first jutsu under a new objective. Students on their way
-- to the former one go on to their jutsu instead, with the experience it still owed them.
UPDATE `UserData`
SET `earnedExperience` = `earnedExperience`
      + IF(CAST(`questData` AS CHAR) REGEXP '"id": "tArna"[^}]*"collected": true', 0, 500),
    `questData` = CAST(REPLACE(CAST(`questData` AS CHAR),
      '"selectedNextObjectiveId": "tArna"', '"selectedNextObjectiveId": "tJtsu"') AS JSON)
WHERE CAST(`questData` AS CHAR) LIKE '%"selectedNextObjectiveId": "tArna"%';

