INSERT INTO `AiProfile` (`id`, `userId`, `jutsuLoadoutId`, `rules`, `includeDefaultRules`)
SELECT 'blacksteel-masked-courier-ai', 'blacksteel-masked-courier', NULL, p.`rules`, p.`includeDefaultRules`
FROM `AiProfile` AS p WHERE p.`id` = (SELECT `aiProfileId` FROM `UserData` WHERE `userId` = 'clik9wpb0000009l606opg0zj')
ON DUPLICATE KEY UPDATE `id` = `AiProfile`.`id`;
INSERT INTO `UserJutsu` (`id`, `userId`, `jutsuId`, `level`, `experience`, `equipped`)
SELECT CONCAT('bs-courier-', j.`jutsuId`), 'blacksteel-masked-courier', j.`jutsuId`, j.`level`, j.`experience`, j.`equipped`
FROM `UserJutsu` AS j WHERE j.`userId` = 'clik9wpb0000009l606opg0zj'
ON DUPLICATE KEY UPDATE `id` = `UserJutsu`.`id`;
-- Each of the pup's animations is played with the rogue's matching sheet.
INSERT INTO `AiSpriteAnimation` (`userId`, `actionKey`, `animationId`)
SELECT 'blacksteel-masked-courier', pup.`actionKey`, CASE
  WHEN pup.`actionKey` = 'idle' THEN 'sprite-20261105-60ab311f15ee3ab516b7-idle'
  WHEN pup.`actionKey` = 'move' THEN 'sprite-20261106-60ab311f15ee3ab516b7-move'
  WHEN pup.`animationId` LIKE '%-strike' THEN 'sprite-20261107-99044fed3b2e5f1a-strike'
  WHEN pup.`animationId` LIKE '%-guard' THEN 'sprite-20261107-99044fed3b2e5f1a-powerup'
  ELSE 'sprite-20261107-99044fed3b2e5f1a-ranged' END
FROM `AiSpriteAnimation` AS pup WHERE pup.`userId` = 'clik9wpb0000009l606opg0zj'
ON DUPLICATE KEY UPDATE `animationId` = `AiSpriteAnimation`.`animationId`;

