UPDATE `Quest` SET `name` = 'Chapter 8: The Ledger', `image` = 'https://ui0arpl8sm.ufs.sh/f/Hzww9EQvYURJAGTDCcoZUC4muiGcQNzjfEndY5y1w20B8hTW', `description` = 'Archivist Sora is studying the shard from the pup''s collar. Someone paid a fortune for that metal, and the village ledgers know who.', `successDescription` = 'The case file on the shard is open, and your name is on it.', `questType` = 'starter', `questRank` = 'D', `requiredLevel` = 5, `maxLevel` = 50, `prerequisiteQuestId` = NULL, `hidden` = FALSE, `consecutiveObjectives` = TRUE, `content` = CAST('{"entryItems":[],"isolated":false,"objectives":[{"structureAssetId":"","locationName":"","locationDescription":"","structureScale":1,"id":"d0","description":"Settled in, Genin? Good. The shard the courier dropped has been with <b>Archivist Sora</b> since your graduation, and Sora has questions only you can answer. The archive is right here in the academy. Mind your manners: Sora bites harder than any dummy.","successDescription":"","nextObjectiveId":[{"text":"Meet Archivist Sora","nextObjectiveId":"d1"}],"sceneBackground":"HJLTJ1RGIhR0g-QztlCQF","sceneCharacters":["alsLzZGTl2s2Tag9zmKVv"],"reward_hunter_items":false,"reward_hunter_items_ids":[],"reward_gathering_items":false,"reward_gathering_items_ids":[],"reward_seichi_silver":0,"reward_money":0,"reward_clanpoints":0,"reward_anbupoints":0,"reward_exp":0,"reward_tokens":0,"reward_prestige":0,"reward_reputation":0,"reward_skillpoints":0,"reward_rank":"NONE","reward_village_membership":"NONE","reward_items":[],"reward_jutsus":[],"reward_bloodlines":[],"reward_sage_modes":[],"reward_badges":[],"reward_titles":[],"reward_medical_experience":0,"reward_hunting_experience":0,"reward_crafting_experience":0,"reward_gathering_experience":0,"reward_sage_mastery_experience":0,"reward_war_damage":0,"reward_war_healing":0,"attackers":[],"attackers_scaled_to_user":false,"attackers_scale_gains":1,"attackers_max_per_battle":1,"task":"dialog","image":"https://uploadthing.b-cdn.net/