UPDATE `Quest` SET `name` = 'Chapter 16: Deployment', `image` = 'https://ui0arpl8sm.ufs.sh/f/Hzww9EQvYURJAGTDCcoZUC4muiGcQNzjfEndY5y1w20B8hTW', `description` = 'The pup you rescued led a Bondkeeper patrol to a hidden entrance. The Order of Black Steel has a stronghold, and Genin teams are going in.', `successDescription` = 'Deployment order issued. Report to the stronghold.', `questType` = 'starter', `questRank` = 'D', `requiredLevel` = 24, `maxLevel` = 50, `prerequisiteQuestId` = 'I8UmQH2-Hei-hRrA-vP6f', `hidden` = FALSE, `consecutiveObjectives` = TRUE, `content` = CAST('{"entryItems":[],"isolated":false,"objectives":[{"structureAssetId":"","locationName":"","locationDescription":"","structureScale":1,"id":"d1","description":"Sora is on their feet when you arrive. The pup you rescued led a Bondkeeper patrol straight to a hidden entrance in the ridges: a stronghold of blacksteel, lit from inside with violet. Genin teams are being sent in to map the operation and disrupt it.","successDescription":"","nextObjectiveId":[{"text":"Accept the deployment","nextObjectiveId":"d2"}],"sceneBackground":"_Ca4nBppDdevDwBICFPUF","sceneCharacters":["Ujjb0ahNxfBnxR5ieZUkn"],"reward_hunter_items":false,"reward_hunter_items_ids":[],"reward_gathering_items":false,"reward_gathering_items_ids":[],"reward_seichi_silver":0,"reward_money":0,"reward_clanpoints":0,"reward_anbupoints":0,"reward_exp":0,"reward_tokens":0,"reward_prestige":0,"reward_reputation":0,"reward_skillpoints":0,"reward_rank":"NONE","reward_village_membership":"NONE","reward_items":[],"reward_jutsus":[],"reward_bloodlines":[],"reward_sage_modes":[],"reward_badges":[],"reward_titles":[],"reward_medical_experience":0,"reward_hunting_experience":0,"reward_crafting_experience":0,"reward_gathering_experience":0,"reward_sage_mastery_experience":0,"reward_war_damage":0,"reward_war_healing":0,"attackers":[],"attackers_scaled_to_user":false,"attackers_scale_gains":1,"attackers_max_per_battle":1,"task":"dialog","image":"https://uplo