-- Chapter 16: Debrief
UPDATE `Quest` SET `name` = 'Chapter 16: Debrief', `image` = 'https://ui0arpl8sm.ufs.sh/f/Hzww9EQvYURJAGTDCcoZUC4muiGcQNzjfEndY5y1w20B8hTW', `description` = 'You walked into the Order of Black Steel''s stronghold and walked back out. Sora wants every detail.', `successDescription` = 'Debrief complete. Genin Trials graduate on record.', `questType` = 'starter', `questRank` = 'D', `requiredLevel` = 10, `maxLevel` = 50, `prerequisiteQuestId` = 'iUnQO8Fek3yJ-tL4Djv99', `hidden` = FALSE, `consecutiveObjectives` = TRUE, `content` = CAST('{"entryItems":[],"isolated":false,"objectives":[{"structureAssetId":"","locationName":"","locationDescription":"","structureScale":1,"id":"d1","description":"Sora listens to your report without interrupting once: the operatives, the aberration of iron, the obelisk, the machinery drinking violet light. When you finish, they set a badge on the desk, and the two shards beside it. These go to the <b>Science Building</b>; its researchers will want to know what blacksteel does to chakra.","successDescription":"","nextObjectiveId":[{"text":"Take the badge","nextObjectiveId":"d2"}],"sceneBackground":"_Ca4nBppDdevDwBICFPUF","sceneCharacters":["Ujjb0ahNxfBnxR5ieZUkn"],"reward_hunter_items":false,"reward_hunter_items_ids":[],"reward_gathering_items":false,"reward_gathering_items_ids":[],"reward_seichi_silver":0,"reward_money":0,"reward_clanpoints":0,"reward_anbupoints":0,"reward_exp":0,"reward_tokens":0,"reward_prestige":0,"reward_reputation":0,"reward_skillpoints":0,"reward_rank":"NONE","reward_village_membership":"NONE","reward_items":[],"reward_jutsus":[],"reward_bloodlines":[],"reward_sage_modes":[],"reward_badges":[],"reward_titles":[],"reward_medical_experience":0,"reward_hunting_experience":0,"reward_crafting_experience":0,"reward_gathering_experience":0,"reward_sage_mastery_experience":0,"reward_war_damage":0,"reward_war_healing":0,"attackers":[],"attackers_scaled_to_user":false,"attackers_scale_gains":1,"attackers_max_per_battle":1,"task":"