-- Chapter 17: Exam Prep
INSERT INTO `Quest` (`id`, `name`, `image`, `description`, `successDescription`, `questType`, `questRank`, `requiredLevel`, `maxLevel`, `prerequisiteQuestId`, `hidden`, `consecutiveObjectives`, `content`) VALUES ('blacksteel-ch17-exam-prep', 'Chapter 17: Exam Prep', 'https://ui0arpl8sm.ufs.sh/f/Hzww9EQvYURJAGTDCcoZUC4muiGcQNzjfEndY5y1w20B8hTW', 'The Chunin Exams open at level 27. Lemu has one last lesson before you sit them.', 'Lemu signs your exam papers. The Chunin Exams wait at the Academy.', 'starter', 'D', 26, 50, 'jYyTQ5Ead2o3i5kzFSH2m', FALSE, TRUE, CAST('{"entryItems":[],"isolated":false,"objectives":[{"structureAssetId":"","locationName":"","locationDescription":"","structureScale":1,"id":"q0","description":"So, the Genin who walked out of a blacksteel stronghold. The Chunin Exams open at level 27, and their first test is written: the proctors ask what jutsu <b>tags</b> do. Let''s see what you remember. Which tag creates a temporary health bar that lasts a few rounds?","successDescription":"","nextObjectiveId":[{"text":"Shield","nextObjectiveId":"q1"},{"text":"Absorb","nextObjectiveId":"q0x"},{"text":"Reflect","nextObjectiveId":"q0x"}],"sceneBackground":"HJLTJ1RGIhR0g-QztlCQF","sceneCharacters":["alsLzZGTl2s2Tag9zmKVv"],"reward_hunter_items":false,"reward_hunter_items_ids":[],"reward_gathering_items":false,"reward_gathering_items_ids":[],"reward_seichi_silver":0,"reward_money":0,"reward_clanpoints":0,"reward_anbupoints":0,"reward_exp":0,"reward_tokens":0,"reward_prestige":0,"reward_reputation":0,"reward_skillpoints":0,"reward_rank":"NONE","reward_village_membership":"NONE","reward_items":[],"reward_jutsus":[],"reward_bloodlines":[],"reward_sage_modes":[],"reward_badges":[],"reward_titles":[],"reward_medical_experience":0,"reward_hunting_experience":0,"reward_crafting_experience":0,"reward_gathering_experience":0,"reward_sage_mastery_experience":0,"reward_war_damage":0,"reward_war_healing":0,"attackers":[],"attackers_scaled_to_user":false,"attackers_scale_gains":1,"attackers_max_per_battle":1,"task":"dialog","image":"https://uploadthing.b-cdn.net/f/Hzww9EQvYURJpIn7vsbKBAOsGCHyl3Sk0mZFrgWPUdjMJ75D.webp"},{"structureAssetId":"","locationName":"","locationDescription":"","structureScale":1,"id":"q0x","description":"Not quite. <b>Absorb</b> turns damage you take into health, chakra or stamina, and <b>Reflect</b> sends damage back at the attacker. The one that gives you a temporary health bar is <b>Shield</b>. Remember it; the proctors will ask.","successDescription":"","nextObjectiveId":[{"text":"Got it. Next question","nextObjectiveId":"q1"}],"sceneBackground":"HJLTJ1RGIhR0g-QztlCQF","sceneCharacters":["alsLzZGTl2s2Tag9zmKVv"],"reward_hunter_items":false,"reward_hunter_items_ids":[],"reward_gathering_items":false,"reward_gathering_items_ids":[],"reward_seichi_silver":0,"reward_money":0,"reward_clanpoints":0,"reward_anbupoints":0,"reward_exp":0,"reward_tokens":0,"reward_prestige":0,"reward_reputation":0,"reward_skillpoints":0,"reward_rank":"NONE","reward_village_membership":"NONE","reward_items":[],"reward_jutsus":[],"reward_bloodlines":[],"reward_sage_modes":[],"reward_badges":[],"reward_titles":[],"reward_medical_experience":0,"reward_hunting_experience":0,"reward_crafting_experience":0,"reward_gathering_experience":0,"reward_sage_mastery_experience":0,"reward_war_damage":0,"reward_war_healing":0,"attackers":[],"attackers_scaled_to_user":false,"attackers_scale_gains":1,"attackers_max_per_battle":1,"task":"dialog","image":"https://uploadthing.b-cdn.net/f/Hzww9EQvYURJpIn7vsbKBAOsGCHyl3Sk0mZFrgWPUdjMJ75D.webp"},{"structureAssetId":"","locationName":"","locationDescription":"","structureScale":1,"id":"q1","description":"Good. Next: what does <b>Absorb</b> do?","successDescription":"","nextObjectiveId":[{"text":"Turns damage taken into health, chakra or stamina","nextObjectiveId":"d1"},{"text":"Sends damage back to the attacker","nextObjectiveId":"q1x"},{"text":"Stuns the target","nextObjectiveId":"q1x"}],"sceneBackground":"H